package com.gophisb.houd11;
import android.Manifest;import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.webkit.*;import androidx.annotation.Nullable;import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity{
 private WebView w;
 @Override public void onCreate(@Nullable Bundle b){super.onCreate(b);w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(false);s.setMediaPlaybackRequiresUserGesture(false);w.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String u){super.onPageFinished(v,u);String js="(function(){function s(){try{if(!window.App||!App.state||!App.state.times||!window.Houd11Android)return setTimeout(s,500);var ks=[\"fajr\",\"dhuhr\",\"asr\",\"maghrib\",\"isha\"],n=new Date();for(var d=0;d<2;d++){var x=new Date(n);x.setDate(x.getDate()+d);x.setSeconds(0,0);ks.forEach(function(k){var t=App.state.times[k];if(!t)return;var q=t.split(\":\").map(Number);x.setHours(q[0],q[1],0,0);if(x.getTime()>Date.now())Houd11Android.scheduleAdhan(k,x.getTime());});}if(typeof App.playAdhan===\"function\")App.playAdhan=function(){Houd11Android.playAdhanNow();};setTimeout(s,60000);}catch(e){setTimeout(s,1000);}}s();})();";v.evaluateJavascript(js,null);}});w.addJavascriptInterface(new Bridge(this),"Houd11Android");w.loadUrl("file:///android_asset/web/index.html");if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1001);}
 static final class Bridge{final Activity a;Bridge(Activity x){a=x;}@JavascriptInterface public void scheduleAdhan(String p,long t){AdhanReceiver.schedule(a,p,t);}@JavascriptInterface public void playAdhanNow(){Intent i=new Intent(a,AdhanService.class).setAction(AdhanService.ACTION_PLAY);if(Build.VERSION.SDK_INT>=26)a.startForegroundService(i);else a.startService(i);}@JavascriptInterface public void openExactAlarmSettings(){if(Build.VERSION.SDK_INT>=31)try{a.startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM, Uri.parse("package:"+a.getPackageName())));}catch(Exception ignored){}}}
}